    Bug 1941471 - Improve the tags matching SQLite function. r=mkmelin

    This should improve the performance of the function by running through the haystack only once
    looking for the needle, rather than splitting the haystack up and checking if one of the tokens is
    the needle.

    Differential Revision: https://phabricator.services.mozilla.com/D279815

diff --git a/mailnews/db/panorama/src/DatabaseUtils.cpp b/mailnews/db/panorama/src/DatabaseUtils.cpp
index 56ae6c5defe..ae99fc3d830 100644
--- a/mailnews/db/panorama/src/DatabaseUtils.cpp
+++ b/mailnews/db/panorama/src/DatabaseUtils.cpp
@@ -69,15 +69,38 @@ NS_IMETHODIMP TagsMatchFunction::OnFunctionCall(

     nsAutoCString haystack;
     aArguments->GetUTF8String(0, haystack);
+    size_t haystackLength = haystack.Length();
+    size_t h = 0;
+
     nsAutoCString needle;
     aArguments->GetUTF8String(1, needle);
-
-    for (auto field : haystack.Split(' ')) {
-      if (field.Equals(needle)) {
-        found = true;
-        break;
+    size_t needleLength = needle.Length();
+    size_t n = 0;
+
+    bool matchingStart = true;
+    for (; h < haystackLength; ++h) {
+      char c = haystack[h];
+      if (c == ' ') {
+        // At the end of a token.
+        if (n == needleLength) {
+          // Found the needle. Stop.
+          found = true;
+          break;
+        }
+        // Reset.
+        matchingStart = true;
+        n = 0;
+      } else if (matchingStart && n < needleLength && c == needle[n]) {
+        // In a token and it matches the needle so far.
+        n++;
+      } else {
+        // In a token and it doesn't match the needle.
+        matchingStart = false;
       }
     }
+    if (h == haystackLength && n == needleLength) {
+      found = true;
+    }
   }

   nsCOMPtr<nsIVariant> result =
